cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _frogSymbols: [],
    },

    createFrogSymbol(id, data, posY) {
        let cfg = cc.vv.gameData.getGameCfg();
        let node = cc.instantiate(this._symbolTemplete);
        node.parent = cc.find("frog_parent", this.node);
        let scp = node.addComponent(cfg.scripts.Symbols)
        node.zIndex = 1000;
        cc.log("create frog id " + id);
        scp.ShowById(id, data);
        node.y = posY;
        this._frogSymbols.push(scp);
        return node;
    },

    getFrogSymbols() {
        return this._frogSymbols;
    },

    //旋转
    StartMove:function(){
        this._result = null
        //回收增加的卷轴
        let cfg = cc.vv.gameData.getGameCfg()
        // if(this._symbols.length > (cfg.row+1)){
        //     this.AddCount(-(this._symbols.length -(cfg.row+1)))
        // }

        this._curY = 0
        this._bMoving = true
        this._bStoping = false
        this._offsetY = 0

        //所有symbols进入旋转状态
        for(let i = 0; i < this._symbols.length; i++){
            let symbol = this._symbols[i]
            symbol.StartMove()
        }
        this._speed = cfg.speed
        this._offset = cfg.symbolSize.height
    },

    //列停止
    OnReelSpinEnd:function(){
        // this._reelState = []
        // let slots = cc.vv.gameData.GetSlotsScript()
        // slots.OnReelSpinEnd(this._reelIdx)
        //
        // //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
        // //停下来的列以及等于最后一列旋转的列，
        // //说明整个列已经停止
        // let lastReelStopIdx = slots.GetLastStopReelIdx()
        // if(this._reelIdx == lastReelStopIdx){
        //     //所有列都停止了
        //     slots.OnSpinEnd()
        // }
    },

    removeFrogSymbols() {
        for (let frogSymbol of this._frogSymbols) {
            frogSymbol.setAnimationToTop(false);
        }
        cc.find("frog_parent", this.node).removeAllChildren();
        cc.find("mask/holder", this.node).removeAllChildren();
        this._symbols = [];
        this._frogSymbols = [];
    }
});