/**墨西哥帅哥-符号表
 *
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    StartMove: function () {
        this._super();

        this.setCoinText(0);
    },

    /**
     * 设置金币显示
     * @param coin
     */
    setCoinText(coin) {
        let text = cc.find("coin", this.node);
        if (coin !== 0) {
            text.getComponent(cc.Label).string = Global.formatNumShort(coin,0);
            text.active = true;
        } else {
            text.active = false;
        }
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id, data){
        let cfg = cc.vv.gameData.getGameCfg();
        if (cc.vv.gameData.GetSlotsScript().isInEpicLink()) {
            if (cfg.frogIds.indexOf(id) === -1) {
                id = cfg.emptyId;
            }
        }

        this._super(id, data);
        
        if (data) {
            this.setCoinText(data);
        }

        if (this._id === cfg.emptyId) {
            this.setCoinText(0);
        }
    },

    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name !== ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    playidleAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            this._state = "idle";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].idle_ani.name !== ""){
                aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }
        }
        return isPlay
    },

    setTopAniNode(node) {
        this._topAniNode = node;
    },

    
    // update (dt) {},
});
