cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    OnReelSpinEnd() {
        this._super();

        let allFrog = true;
        for (let i = 0; i < 4; i++) {
            if (cc.vv.gameData.getGameCfg().frogIds.indexOf(this._symbols[i].GetShowId()) === -1) {
                allFrog = false;
                break;
            }
        }
        if (allFrog) {
            for (const symbol of this._symbols) {
                symbol.playStopAnimation();
            }
            cc.vv.AudioManager.playEff("games/TheFrogPrince/", "bonus_notify", true);
        }

        if (this._reelIdx === 4 && !cc.vv.gameData.GetSlotsScript().isFullFrogOneColumn()) {
            for (const symbol of this._symbols) {
                if (symbol.GetShowId() === cc.vv.gameData.getGameCfg().bonusId) {
                    symbol.playWinAnimation();
                    break;
                }
            }
        }
    },

    OnReelBounsActionBefore() {
        this._super();

        if (this._reelIdx === 4) {
            for (const symbol of this._symbols) {
                if (symbol.GetShowId() === cc.vv.gameData.getGameCfg().bonusId) {
                    symbol.playStopAnimation();
                    break;
                }
            }
        }
    },

    //增加卷轴
    //count 变化的个数
    //deltaTime 变化的时间
    //offsetY y方向偏移（0～1）个格子高度. 专门用于那种默认就显示3个半的那种情况
    AddCount:function(count,deltaTime=0.5,offsetY=0){
        // 只增加背景长度，不填充symbol，也不重新排列
        if(this._bResizing) {
            return;
        }

        this._bResizing = true;
        this._nCount += count;
        this._offsetY = offsetY;
        let nOffCount = this._offsetY;
        if(count < 0){
            nOffCount = (this._offsetY*-1);
        }

        let cfg = cc.vv.gameData.getGameCfg();
        this.totalAddHeight = (count-nOffCount) * (cfg.symbolSize.height);
        this.deltaHeight = this.totalAddHeight / deltaTime;
        this.curAddHeight = 0;
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask ,
    //reels_bg/bg*,
    GetResizeHeightObjs:function(){
        let objs = []

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            objs.push(bg)
        }

        // line
        objs.push(cc.find("reels_frame_bottom/line_" + this._reelIdx, this.node.parent.parent));
        objs.push(cc.find("reels_frame_bottom/line_" + (this._reelIdx + 1), this.node.parent.parent));

        return objs;
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame
    GetResizeMoveingObjs:function(){
        let objs = []

        let frameTop = cc.find(cc.js.formatStr("reels_frame/top_%s",this._reelIdx + 1), this.node.parent.parent);
        if(frameTop){
            objs.push(frameTop);
        }
        return objs;
    },

    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        this._super(bShow, name);
        
        if (bShow === false) {
            if(this._stopRightNow){
                cc.vv.AudioManager.stopEffectByName("reel_notify");
            }
        }

        let node = cc.find("mask/" + name,this.node)
        if(node){
            node.active = bShow
        }
        else{
            cc.log("未找到加速节点：mask/node_anti");
        }
    },

    getSymbols() {
        return this._symbols;
    }
});